import sys

def find_maximal_sequence(fragments):
    n = len(fragments)
    graph = {i: [] for i in range(n)}

    for i in range(n):
        for j in range(n):
            if i != j:
                suffix = fragments[i][-5:]
                prefix = fragments[j][:5]
                if suffix == prefix:
                    graph[i].append(j)

    def dfs(node, visited, path):
        visited.add(node)
        path.append(node)

        if len(graph[node]) == 0:
            return path

        for neighbor in graph[node]:
            if neighbor not in visited:
                result = dfs(neighbor, visited, path)
                if result:
                    return result

        path.pop()
        visited.remove(node)
        return None

    max_path = []
    for i in range(n):
        path = dfs(i, set(), [])
        if len(path) > len(max_path):
            max_path = path

    return max_path

def reconstruct_text(fragments, max_path):
    if not max_path:
        return "AMBIGUOUS"

    reconstructed_text = fragments[max_path[0]]
    for i in range(1, len(max_path)):
        fragment = fragments[max_path[i]]
        overlap = len(fragment) - len(fragment.lstrip(fragments[max_path[i-1]][:5]))
        reconstructed_text += fragment[overlap:]

    return reconstructed_text

def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    fragments = data[1:]

    max_path = find_maximal_sequence(fragments)
    result = reconstruct_text(fragments, max_path)

    print(result)

if __name__ == "__main__":
    main()
